const t = ($json.text_trim || '').trim();
const m = t.match(/^\/(new|list|done|delete|cancel)(?:\s+(.+))?$/i);
return [{
  ...$json,
  command: m ? m[1].toLowerCase() : '',
  arg: (m && m[2]) ? m[2].trim() : ''
}];

