  text = '📭 Открытых задач нет.\n\nДобавить новую: /new';
} else {
    const lines = rows.map((r) => `- ${r.text} (<code>${r.id}</code>)`);

  const headline = '📌 <b>Открытые задачи</b>'
  text = headline + '\n\n' + lines.join('\n');
}

return [{ chat_id: $json.chat_id, text }];

const data = ($json.callback_data || '').trim();

// done:<id> / del:<id>
let m = data.match(/^(done|del):(.+)$/);
if (m) {
  const id = Number(m[2]);
  return [{
    ...$json,
    cb_action: m[1],
    cb_row_id: Number.isFinite(id) ? id : null
  }];
}

// confirm add
if (data === 'add_draft' || data === 'cancel_draft') {
  return [{
    ...$json,
    cb_action: data,
    cb_row_id: null
  }];
}

return [{ ...$json, cb_action: '', cb_row_id: null }];

const items = $input.all().map(i => i.json);
let rows = items;
if (items.length === 1 && Array.isArray(items[0].data)) rows = items[0].data;

let text;
let reply_markup;

if (!rows || rows.length === 0) {
  text = '📭 Открытых задач нет.\n\nДобавить: /new';
  reply_markup = { inline_keyboard: [] };
} else {
  const lines = rows.map((r, idx) => `${idx+1}. [${r.id}] ${r.text}`);
  const keyboard = rows.map(r => ([
    { text: '✅ Done', callback_data: `done:${r.id}` },
    { text: '🗑 Delete', callback_data: `del:${r.id}` }
  ]));
  text = '📋 **Твои задачи**\n\n' + lines.join('\n') + '\n\n' +
         'Закрыть: `/done <id>`\nУдалить: `/delete <id>`';
  reply_markup = { inline_keyboard: keyboard };
}

return [{ chat_id: $json.chat_id, message_id: $json.message_id, text, reply_markup }];

